function demoMain(idx,label){
  var files=[["a.js",[1,1,1,0,1]],["b.js",[1,0,0,0,1]],["c.js",[1,1,1,1,1]]];
  var f=files[idx%files.length];var hit=f[1].filter(function(x){return x;}).length;
  var pct=Math.round(hit/f[1].length*100);
  return "["+label+"] "+f[0]+": "+hit+"/"+f[1].length+" lines covered ("+pct+"%) "+(pct>=80?"MEETS 80% GATE":"BELOW GATE");
}

